const r = "C:\\Users\\jjq21\\Desktop\\github\\My-second-brain";
const q = JSON.stringify(r);
const cmd = [
  "'════ 远端是否存在 reddit存档 ════'",
  "git -C " + q + " ls-tree -r --name-only origin/main | Select-String 'reddit'",
  "'════ 远端 40-产出 文件数 ════'",
  "'count: ' + (git -C " + q + " ls-tree -r --name-only origin/main -- '40-' | Measure-Object).Count",
  "'════ 远端 情报 目录 ════'",
  "git -C " + q + " ls-tree -r --name-only origin/main -- '40-产出/情报'",
  "'════ 本地被忽略的文件 ════'",
  "$ig = git -C " + q + " status --ignored -s --untracked-files=normal; $ig | Select-Object -First 20",
  "'════ 本地工作区文件 vs 远端跟踪文件（有无本地独有）════'",
  "$local = Get-ChildItem -Recurse " + q + " -File -Force | Where-Object { $_.FullName -notmatch '\\\\\\.git\\\\' } | ForEach-Object { $_.FullName.Substring(" + q.length + " + 1) };",
  "'本地文件总数(不含.git): ' + $local.Count",
].join("; ");
const res = await tools.pwsh({ command: cmd, description: "Targeted check for archive file and ignored files", timeoutMs: 180000 });
console.log(res.kind === "foreground" ? (res.stdout.text + res.stderr.text).slice(0, 4000) : JSON.stringify(res));
